            printf("Target port %d: %s\n", i + 1, port_range[i]);
            break;
        }
    }

    // Open ports: 22, 23, 25, 80, 8080
    for (int i = 0; i < flags; i++) {
        if (scanf("%s", &port_range[i]) != 0) {
            printf("Open port %d\n", i + 1);
